) AS (
  VALUES 
    (311::BIGINT, 'humilla a los estudiantes, las tareas que deja son EXCESIVAMENTE largas y complicadas, todas las semanas deja lecturas. Exámenes muy largos, se sufre mucho. Si matriculó con él pulsee todos los puntos extra que pueda'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, '68e0596422b0e48b197976c1f0170525107ff13e280305abb9f4e1e0899a1094'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Es narcisista, humilla a los estudiantes en clase, pierde demasiado el tiempo de lecciones. Sus lecciones se basan en mejengas, el leyendo su libro y si usted tiene una pregunta, siempre hara que suene estupida. Resumenes de lecturas todas las semenas y tareas PESADISIMAS bisemenal. Haga pts extra'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, '099a297ad1e061bbd0dc9573e4ec07f358715fb9235a960ef9bcab323e9e7b94'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'El curso se llama Arquitectura pero el da un curso intensivo de ensamblador. Pierde tiempo hablando de mejengas y hay que escucharlo insultando a quienes apoyan a x político. Matricule si quiere experimentar síndrome de Estocolmo.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2025-11-28T00:00:00+00:00'::TIMESTAMPTZ, '8778f36aca3dc1a003e8af7355fb0fb49acf3349dacb937e6bbb0cbc1b65a00a'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'No matriculé con el, este mae es un hp y tiene la tendencia de humillar a sus alumnos por no saber algo en primer semestre, quiérase de verdad'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2025-11-06T00:00:00+00:00'::TIMESTAMPTZ, '984786e634266a99ac1224fda55a522f584a6555a720489962e896e8f740031a'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'SI quiere matricular con el o le toco porque no había cupos, sepa que va a sufrir como nunca lo ha hecho. Examenes de 9 horas de 200 preguntas. 5 horas por lecturas a la semana , que acumulan entre 140 en el semestre + siempre un brete bisemanal de mínimo 30 horas, 50 en algunos casos . 50 EX/50 Lec'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2025-08-29T00:00:00+00:00'::TIMESTAMPTZ, '9a7e369c803e5b582e0143aae0e1b5b6a604f8fab96d038f7ac2be5139b8e6e4'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Simplemente no, por favor quierase un poco y matricule con alguien más que no sea Kirstein o Benavides, es por su propio bien'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '1af1500c7c5d7e75b64ebbbbeeb28820d05674a93e1ef64eb1e4f5db3cad555e'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Es muy exigente, se hacen entre 130 y 160 resumenes por semestre, las tareas son MUY largas y dificiles, los examenes son los domingos desde las 8 y duran entre 6 y 8 horas, es muy malo explicando pues solo se sienta y empieza a hablar paja, tambien pierde tiempo al inicio con sus "mejengas".'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2024-05-04T00:00:00+00:00'::TIMESTAMPTZ, 'e90e846a098a8f4b7b0e4780a4f3a04c1572f437b697cabe28eb342089aa3277'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-04-25T00:00:00+00:00'::TIMESTAMPTZ, 'f8322de74ceee34697b8c2b207616a3b774b600c41f321c6e9936813c99b472b'::TEXT, ARRAY[1019]::BIGINT[]),
    (311::BIGINT, 'Después de mi primer año en el tec mi mayor arrepentimiento a sido matricular con el, lleva un ritmo inhumano casi que debería de multiplicar los créditos totales x2, no explica bien solo lee, es mega prepotente por lo tanto no se le puede preguntar nada, y por ultimo examen los domingos.....'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'a40223c022627bac1d6703846fb57c2c5b2900ad50f2680f3553f545ed85cc27'::TEXT, ARRAY[1032, 1017]::BIGINT[]),
    (311::BIGINT, 'Las tareas son infinitas, deja mínimo 3/4 resumenes semanales de capitulos de 10-100 páginas, los quizzes ni piense que va a poder terminarlos a tiempo en las 2 horas de clase. Los examenes son en domingo y duran 6 horas. No cometa mi error de matricular con él llevando bloque completo'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2023-03-24T00:00:00+00:00'::TIMESTAMPTZ, 'c0a28196896926747086d545f29c5fb8ad44339c510fab7998aac6ca15539e77'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Es de los profesores más malos de la historia. No sabe lo que es trabajar en otra cosa que no sea dar clases. A los estudiantes que trabajan los tiene entre ojos. No sabe nada del mundo real empresarial.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-03-18T00:00:00+00:00'::TIMESTAMPTZ, '92ca888c4d5aa84951b1ee38e649abb9f0637416f0b245edbd9229248b328c01'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'NO matriculen con este profe, no sean tontos y no comentan ese error es lo peor que pueden hacer es un muyyyyy mal profe, no explica, se la pasa sentado, deja trabajos exageradamente largos, y los examenes son de mas de 180 preguntas los domingos y dura más de 6 horas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2023-03-02T00:00:00+00:00'::TIMESTAMPTZ, '2af2f2146d3c81996ff0f626290f9a9f3001d6abe44897dad5d077f514926951'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Definitivamente no matriculen con este profesor, fácil podría describirlo como el profe mas anticuado del TEC, el mae piensa que los estudiantes solo están llevando solamente ese curso, deja infinidad de tareas por semana de verdad es de otro mundo, usa métodos de enseñanza muy anticuados.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2022-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'b6255fcd0ef7bf8cd56faf97224de423b5c690ed57a5737751046dfb75209fc4'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'No vuelvo a matricular con este señor, en mi vida. Aunque tenga que esperarme un semestre para cursar la materia. Él piensa que solo se lleva esa materia. Es demasiado trabajo y muy difícil. DEMASIADO. Porfavor, si valora su salud mental, no matricule con este señor. Se los ruego.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2022-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'cad46b3e88af614184b86c455a48b256176cd3cd5702a160fa30cbf222313d60'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'No se haga el daño de matricular con este mae.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-10-04T00:00:00+00:00'::TIMESTAMPTZ, '1f0f06cdb3fdf6e07ab79e931d16aa3b783f0f0c4ab7932511c94f05ea957cc5'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Mae no metan con este señor, el peor profe del TEC.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-09-10T00:00:00+00:00'::TIMESTAMPTZ, '19ca25252ab0e2397de2a54dd4b6fc8d9085b3e534b21ee961b5a6009aaebd0c'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Es un asco de profe, simplemente no matrícule con él'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'b17d14b31a38a5ff69676fa119fed6252d0eba4d6a55e665a5613ebf9e64b22c'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'No sé que es peor, el profesor con su arrogancia y desdén con los estudiantes o los "fans" que dicen que es buenísimo porque "es que matarse y no dormir es aprender". El peor profesor de la vida, ni a mi peor enemigo se lo recomendaría'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'e79fbe8c34c4e9ec895cc1ae7896b247607aaf011a168e11b1e80bf9bdb0db8c'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Si esta aquí por que es su única opción matricule en otra sede. Es el peor profesor junto con benavides. Tareas largas y sin sentido. Es machista, se nota ñas preferencias, la materia no tiene nada que ver con los demás cursos de la carrera. En serio esta mejor sin matricular, no lo haga compa'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2022-04-15T00:00:00+00:00'::TIMESTAMPTZ, '967baef22c42c961b498149f8119b2ec5f0b0f32d62e77097d6e20109c58a4d9'::TEXT, ARRAY[1017, 1032]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-12T00:00:00+00:00'::TIMESTAMPTZ, '6a1dd130c3f9ee1c53f5d62e5dcfa6dec9de1f44ba65ac9de7bb75c7a541e479'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Mucha cantidad, poca calidad. El profe lleva como 2 siglos dando los mismos cursos, por lo que conoce muy bien la materia. Tiene preferencia por algunos estudiantes, lo que resulta bastante evidente. La carga es excesiva'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, '679fabfd0710a41853e173f3ad6fb9b492e24bfa3a7407f4535639c551884a65'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'El profe es muy simpático y si ve que uno la pulsea le ayuda. Da muchos puntos extras y son muy sencillos. Hasta ir a clases te da puntos. Todas las semanas hay que entregar resúmenes, pero son notas regaladas. Deja tareas largas y exámenes largos. Yo que sentía que me iba a morir termine con 90.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'b77aaff9954ee3967989ff52e27cf4edd778db2800fce49aeb5420da62371379'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Me gustaba mucho la materia, sin embargo las tareas eran eternas al igual que los exámenes, por lo que consumía mucho tiempo entonces no se disfruta el curso. Cabe recalcar que sé organizar súper bien mi tiempo e igual habían trabajos que no lograba terminar, para que lo tomen en cuenta :)'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'deab6d4379f89f90e57c011c6ae90660b29460244db22a1a063c3266c4c3c82e'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Consume mucho tiempo pero ayuda bastante si uno se lo pide, las clases son solo ejemplos por lo que hay que leer de antemano la materia y hay muchos trabajos con puntos extra'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '10bf93252806c94837e34fbc6757926d26f13d86c7b153af7ffd2a2d89b57f5a'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'No lo recomiendo. Consume mucho tiempo para al final aprender muy poco. No explica claro. Las clases son casi solo el programando.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-07-11T00:00:00+00:00'::TIMESTAMPTZ, '4dbb840f71f66ffdaebb916cebd1223dd9348fa68c88526cb2719afd4c499564'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'En virtual deja la misma cantidad de tareas que presencial, que son bastantes. Pero al ser tantas no ocupa nota perfecta para pasar, con solo hacerlas está bien. Siempre aclara dudas, los exámenes son largos y difíciles, da muchas ayudas extras para que todos los que hagan sus tareas pasen'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '72c99a65d2fca43b84250bed5c9f9176f334f07f3278e7b60ce46adb48b5618e'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'el mae en virtual no explica de manera sincrónica, pero envía su libro y es leer una explicación en clase. Es muy cansado por todos los trabajos pero si le pone desde el principio va a pasarla bien. Da muchos puntos extra, es algo pesado en general.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '4e7d54b80fddd807b95231250662c9813eee42a2d2030b25d5c3194b68336679'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Muchas tareas semanales, en la primera mitad del curso debe leerse 3 capítulos de distintos libros y resumir los cada semana, luego sube a 5. Eso sumado a las tareas se hace mucho trabajo. Usa tecnologías muy antiguas, incluso en una tarea hay que instalarse un programa que necesita Windows xp.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '2f61afc42398599a2f4833bd4a69cd184c9841a694a7b7cd838e52299a9358e5'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Deja demasiadas tareas, no explica bien y hace exámenes muy difíciles.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2020-08-06T00:00:00+00:00'::TIMESTAMPTZ, '2203f97dcc287630f47b36edf96a42267d19e4dc4448a60a16c3d967e3b14a52'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-02-14T00:00:00+00:00'::TIMESTAMPTZ, '93723010be4f97739e294a9b836f4175e304b5afacc1e927d12318bcb963d1d6'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Deja tareas cortas y largas todas las semanas, con que las haga pasa el curso, da muchos puntos extra, los examenes son muy largos y medio dificiles pero bien bien los pasa con 50, todas las tareas se hacen individuales. Es muy pura vida y se aprende bastante, responde dudas'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '22a19fa35ccfbfde7bc7d59f8fec223969b0575e1daf61f010bd4079d5700500'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Pasa hablando de su familia y mejengas, entonces intenta dar la materia en los últimos 20 minutos de clase, por lo que hay que pasar reponiendo clase y no explica bien. Exámenes larguísimos y DEMASIADOS trabajos. Por algo es que ofrece tantas oportunidades de puntos extra.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, '0e87cf7dd3d1877fe2690bb6e9312a240953bb0c188baa6c609ddb11e1637aa0'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'No lo haga compa'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Muchos exámenes']::TEXT[], '2019-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'f92f89c0d251acc90d2553dc5fefc9f13c51e470ab889794332cb43dc045b28f'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Un curso interesante. Lo considero buen profe para este curso'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '2a81e78c4a996721e24d6e24593843b6fa5ce6253d8e237b3f977530eec4e6e7'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'El vive en la edad de piedra, este profe tiene de poca a 0 experiencia laboral, si quieren saber todo lo que no es la carrera, él da esa materia, si tiene posibilidad con otro profe mejor o adelante otro curso pero no desperdicie su tiempo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2019-04-28T00:00:00+00:00'::TIMESTAMPTZ, '3256514e7e3d811438f5194416b2b6f1cb2546b1aeebaaccc9423bf86146253e'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2019-02-16T00:00:00+00:00'::TIMESTAMPTZ, '96558ea2227dc5b87f7de47e1d66e2bec8b30dc92855085a46dfa53b930ca740'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Si puede meter con otro profe hagalo, cada clase es una agonia y son obligatorias por que sin la nota extra de la asistencia casi nadie pasa por lo que tiene que escuchar 10 minutos de materia y 2h de sus historias , la clase podria durar una hora si el profe diera la materia y no hablara de mejenga'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos']::TEXT[], '2018-12-05T00:00:00+00:00'::TIMESTAMPTZ, '5df7abd2aa710f853c609f91b71b0f3df866355e40cbb36bb273fcecbe4f03ab'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ni tan bueno, ni tan malo. Realmente está un poco sobrevalorado, no le gusta ayudar mucho en clase y fuera de clases es imposible verlo, solo ayuda por correo o por el foro. Se desperdicia mucho algunas clases (muchas) y otras las aprovecha demasiado. Pasarle no es complicado, solo hacer resúmenes.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'f902ab67441c071064fcc16a043f049af0e64eef6ded98b8ee229a24010f4d7a'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Si preguntas algo te responde de manera grosera, no explica muy claro en clases, pero al fin y al cabo se aprende bastante, deja muchas tareas y resúmenes, y se pueden ganar bastantes puntos extras. Sí usted puede soportar la presión de los demás cursos y este que vale como 6 créditos no lo dude.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-12T00:00:00+00:00'::TIMESTAMPTZ, '30c9ce9413d5ef026d9268e1a8262c3902577dfd6753be911342fd31dd075465'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Nadie va a negar que el profe sabe mucho, pero no tiene la dedicación para enseñar. Deja una exageración de trabajos para una semana y los exámenes son domingos de 6 a 7 horas. La única ventaja es que da muchos puntos extras por cualquier cosilla, pero no explica nada bien y pierde mucho tiempo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-10T00:00:00+00:00'::TIMESTAMPTZ, 'e646174995f3afb0807d183edac4400047f12cbbd8e8b7ea966b83618c732ad9'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2018-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'e912c7c6d4f128f54627a71a1b67d90837fb23b684709f16b6b6453efca86499'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2017-11-22T00:00:00+00:00'::TIMESTAMPTZ, '9c6b38a37554109d3431561baf7828bfbbb2ef686099fd77e1df2ffb563d4113'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, '+ Todas las semanas vas a estar haciendo resúmenes(como todos los cursos que da) + El compilador lo vas a construir a pie sin herramientas/frameworks + Si no tienes claro que hacer en una etapa del proyecto, estás jodido porque kirstein no tiene consulta personal + Aprenderas los inútiles automatas'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2017-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'c1c3c7430adf10ac3ddcae6db002aae417d6682dbbfb735f8d2dce130ffb2792'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'Hay que estudiar mucho para pasar el curso, perp con él se aprende demasiado. Es muy estricto con la asistencia y el control de plagio.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '63d8e22f3b7478c0c7732a8fc79c28952bf79370b902015e0fc3f7da79cca3a0'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'El que mejor lo prepara a uno para la dificultad que vendrá a lo largo de la carrera. Siempre hay trabajos que hacer, es bien difícil mantenerse al día. Al final uno siente como que todo el esfuerzo valió la pena y que aprendió en un semestre más que en toda su vida. Al final regala como 10pts extra'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '0e49bebae3e13ddbf839a62c42bb77f4b983401b3ab30b940d365b4ac72f04e7'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'El sabe mucho, los exámenes son estúpidamente largos, las clases entretenidas pero prepárese para pasar estresado y bajo presión todo el semestre'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2017-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'f11d7852c375dd2f4733bebbc24e629ad9a611311da42fa7136e7ea6bc9c8e76'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Es buena gente pero no explica muy bien, deja como 200 tareas por semestre, repone clases, habla paja asi que se distrae y los examenes son como de ocho horas los domingos(no estoy vacilando). Eso si, ayuda bastante y da putos extra'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-14T00:00:00+00:00'::TIMESTAMPTZ, '04929c8f1df6a26fd9b2b3c811fb9fd3dbe217e943ff294083ca2b14454ca478'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Excelente porfesor. Deja tandas de hasta 5 lecturas semanales de las que hay que hacer resumenes. Uno aprende muchisimo de todo porque el conocimiento que el tiene no siempre esta en Google sino hque hay que buscarlo en muchos libros'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2016-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'fead4dbee6e5482db15792f0293f97563042d78ea03c34df054792e39c3ef45a'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2016-02-26T00:00:00+00:00'::TIMESTAMPTZ, 'd3bdf87857bd1915ce70069a1dd68e90b6d16d431c7105a035fe4ed7fb77d939'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Si es primer ingreso, mejor no matricule con él. Kirstein exige mucho y le gusta que usted se asuste.No es fácil pedirle ayuda, sus clases no son claras, se basa en materia viejisima en videobeam, muchas tareas largas, exámenes de 6 horas los fines de semana. Tenés que ponerle mucho desde el inicio.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2016-02-05T00:00:00+00:00'::TIMESTAMPTZ, '25d0159c7ca322aff95735584a1ce63e45fa92b9ae3d586192e3dfc24357eb4f'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Cualquier curso con él se hace muy pesado, muchos resúmenes y proyectos. Las lecturas son bastante profundas y complicadas. Pero si cumple con todo y aún le faltan puntos el ayuda. Tienes que vivir en el foro de IC. Y los exámenes que él hace deberían ser ilegales. Matricule si no hay de otra.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-02-04T00:00:00+00:00'::TIMESTAMPTZ, '1b42daceeae727a1a067d19085f208a26c2d7c2116fdf700af7af11ffb7082cb'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Es muy divertido'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'ac2fcc3ea3bb9517bc41c843a67c192290d298ccaa6a6de01941041f5b7d09cd'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Si llevas Kirstein + 3 o 4 cursos, no te prometo el cielo.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-10T00:00:00+00:00'::TIMESTAMPTZ, '8d2fdb40d845734c517080eac5e1899265c37e6f0db78ad5480a7a19ffcef614'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'No se siente ambiente de respeto en la clase. En el curso de Arqui no daba los temas claros, asumía muchas cosas que no todos sabíamos'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '695bf913af44d201dea8f555077d8a5e03a3d82b8483982a49e106e72bc4fc13'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Uno aprende demaciado con él'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-21T00:00:00+00:00'::TIMESTAMPTZ, '1e3485d817becc58c6f297afc81ccd1d2196ed7c81edf8cbeddcd600f07f8321'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Si usted no es vago, pasa'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '8e88dc2c12f953699e8d7d21b7c4b9d61ed977b4136a8e0f6bcd38762b096468'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Excelente profe, el curso con el es muy matado pero se aprende en demasía de un monton de temas. Si le pone bastante, seguramente pasa.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'b4f8f86bdcae4b6817e67792396879207a6162391b68d242a94eba1799e86442'::TEXT, ARRAY[1017, 1032]::BIGINT[]),
    (311::BIGINT, 'Se aprende demasiado en el curso'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '62a1686ab8d447fe8e535156c217154412c5858461369c09aa869cdc6a1d49b4'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'c2fbc7020a89240ae819716e915ce8af4960297150c8288fa1d773683e467f8c'::TEXT, ARRAY[1017]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
